from dataclasses import dataclass

@dataclass
class Receipt:
    name: str
    cents: int

    def label(self) -> str:
        return f"{self.name}: ${self.cents / 100:.2f}"

print(Receipt("Pencil", 125).label())

def positive_count(text):
    value = int(text)
    if value <= 0:
        raise ValueError("Enter a positive count")
    return value

for text in ["3", "zero", "-2"]:
    try:
        print(positive_count(text))
    except ValueError:
        print("Invalid:", text)

def valid_minutes(values):
    for value in values:
        if 0 <= value <= 180:
            yield value

stream = valid_minutes([12, -1, 45, 400, 20])
print(next(stream))
print(list(stream))

import json
from typing import TypedDict

class Session(TypedDict):
    activity: str
    minutes: int

def parse_session(raw: object) -> Session:
    if not isinstance(raw, dict):
        raise ValueError("expected an object")
    activity, minutes = raw.get("activity"), raw.get("minutes")
    if not isinstance(activity, str) or not activity.strip():
        raise ValueError("activity is required")
    if type(minutes) is not int or minutes < 0:
        raise ValueError("expected nonnegative integer minutes")
    return {"activity": activity, "minutes": minutes}

item = parse_session(json.loads('{"activity":"read","minutes":25}'))
print(f"{item['activity']}: {item['minutes']}")
